// ── Reusable Components ───────────────────────────────────────────────────────

function Input({ label, type = "text", placeholder, value, onChange, hint, autoFocus }) {
  const [focused, setFocused] = useState(false);
  return (
    <div style={{ marginBottom: 16 }}>
      <label style={{ color: theme.textMuted, fontSize: 12, fontWeight: 600, letterSpacing: 0.5, display: "block", marginBottom: 6 }}>
        {label}
      </label>
      <input
        type={type} placeholder={focused ? "" : placeholder} value={value}
        autoFocus={autoFocus}
        onChange={e => onChange(e.target.value)}
        onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}
        style={{
          width: "100%", padding: "13px 14px", borderRadius: 12,
          background: theme.surface,
          border: `1.5px solid ${focused ? theme.accent : theme.border}`,
          color: theme.text, fontSize: 15, outline: "none",
          fontFamily: "inherit", boxSizing: "border-box", transition: "border-color 0.15s",
        }}
      />
      {hint && <p style={{ color: "#ff8888", fontSize: 11, marginTop: 5 }}>{hint}</p>}
    </div>
  );
}

function Btn({ children, onClick, variant = "primary", style: extra = {} }) {
  const variants = {
    primary: { background: "linear-gradient(135deg, #7c5cfc, #a78bfa)", color: "#fff", boxShadow: `0 6px 24px ${theme.accentGlow}`, border: "none" },
    ghost:   { background: "none", color: theme.textMuted, border: `1px solid ${theme.border}` },
  };
  return (
    <button onClick={onClick} style={{
      width: "100%", padding: "15px", borderRadius: 13,
      fontSize: 15, fontWeight: 700, cursor: "pointer", fontFamily: "inherit",
      ...variants[variant], ...extra,
    }}>{children}</button>
  );
}

function Avatar({ initials, color, size = 36 }) {
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%",
      background: `${color}28`, border: `2px solid ${color}66`,
      display: "flex", alignItems: "center", justifyContent: "center",
      color, fontSize: size * 0.33, fontWeight: 700, flexShrink: 0,
    }}>{initials}</div>
  );
}

function BackBtn({ onClick }) {
  return (
    <button onClick={onClick} style={{
      background: "none", border: "none", color: theme.textMuted,
      fontSize: 22, cursor: "pointer", padding: 0, lineHeight: 1, marginBottom: 14,
    }}>←</button>
  );
}

// ── Screen: Onboarding ────────────────────────────────────────────────────────

function FadeIn({ delay = 0, children, style = {} }) {
  const [visible, setVisible] = useState(false);
  useEffect(() => { const t = setTimeout(() => setVisible(true), delay); return () => clearTimeout(t); }, [delay]);
  return (
    <div style={{
      opacity: visible ? 1 : 0,
      transform: visible ? "translateY(0)" : "translateY(20px)",
      transition: "opacity 0.55s cubic-bezier(0.16,1,0.3,1), transform 0.55s cubic-bezier(0.16,1,0.3,1)",
      ...style,
    }}>
      {children}
    </div>
  );
}

