            {plan.badge && <div style={{ position: "absolute", top: -10, right: 16, background: plan.color, color: "#fff", fontSize: 10, fontWeight: 700, padding: "3px 10px", borderRadius: 20, letterSpacing: 1, textTransform: "uppercase" }}>{plan.badge}</div>}
