// ── Screen: Account Settings ─────────────────────────────────────────────────

function AccountSettingsScreen({ onBack, onServers, onUpgrade }) {
  const [name, setName]   = useState("Alex Rivera");
  const [email, setEmail] = useState("alex@example.com");
  const [saved, setSaved] = useState(false);
  const [section, setSection] = useState(null); // "password" | "danger"
  const [oldPass, setOldPass] = useState("");
  const [newPass, setNewPass] = useState("");
  const [passStep, setPassStep] = useState("form"); // "form" | "sent" | "done"
  const [verifyCode, setVerifyCode] = useState("");

  function saveProfile() {
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  }

  function requestPasswordChange() {
    if (!oldPass || newPass.length < 8) return;
    setPassStep("sent");
  }

  function confirmPasswordChange() {
    if (verifyCode.length < 4) return;
    setPassStep("done");
    setTimeout(() => { setPassStep("form"); setSection(null); setOldPass(""); setNewPass(""); setVerifyCode(""); }, 2200);
  }

  const initials = name.split(" ").map(w => w[0]).join("").slice(0,2).toUpperCase();

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", background: theme.bg }}>
      <div style={{ padding: "52px 24px 18px", borderBottom: `1px solid ${theme.border}` }}>
        <BackBtn onClick={onBack} />
        <h2 style={{ color: theme.text, fontSize: 22, fontWeight: 700, fontFamily: "Georgia, serif", marginBottom: 3 }}>Account</h2>
        <p style={{ color: theme.textMuted, fontSize: 13 }}>Manage your profile and security.</p>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "20px 24px 40px" }}>

        {/* Avatar + name hero */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 28 }}>
          <div style={{
            width: 72, height: 72, borderRadius: "50%",
            background: "linear-gradient(135deg, #7c5cfc, #a78bfa)",
            display: "flex", alignItems: "center", justifyContent: "center",
            color: "#fff", fontSize: 26, fontWeight: 700, marginBottom: 10,
            boxShadow: `0 0 28px ${theme.accentGlow}`,
          }}>{initials}</div>
          <div style={{ color: theme.text, fontSize: 16, fontWeight: 600 }}>{name}</div>
          <div style={{ color: theme.textMuted, fontSize: 13 }}>{email}</div>
          <div
            onClick={onUpgrade}
            style={{ marginTop: 8, background: "#7c5cfc18", border: "1px solid #7c5cfc35", borderRadius: 20, padding: "3px 12px", cursor: "pointer", display: "flex", alignItems: "center", gap: 5 }}>
            <span style={{ color: theme.accent, fontSize: 11, fontWeight: 700 }}>FREE PLAN</span>
            <span style={{ color: theme.accent, fontSize: 11 }}>· Upgrade ↗</span>
          </div>
        </div>

        {/* Profile section */}
        <label style={{ color: theme.textMuted, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", display: "block", marginBottom: 10 }}>
          Profile
        </label>
        <div style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 14, padding: "16px", marginBottom: 20 }}>
          <Input label="Display name" placeholder="Your name" value={name} onChange={setName} />
          <Input label="Email" type="email" placeholder="you@example.com" value={email} onChange={setEmail} />
          <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
            <Btn onClick={saveProfile} style={{ flex: 1, padding: "12px" }}>
              {saved ? "✓ Saved" : "Save changes"}
            </Btn>
          </div>
        </div>

        {/* Password section */}
        <label style={{ color: theme.textMuted, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", display: "block", marginBottom: 10 }}>
          Security
        </label>
        <div style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 14, marginBottom: 20, overflow: "hidden" }}>
          <button
            onClick={() => setSection(section === "password" ? null : "password")}
            style={{
              width: "100%", padding: "16px", background: "none", border: "none",
              display: "flex", justifyContent: "space-between", alignItems: "center",
              cursor: "pointer",
            }}>
            <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
              <span style={{ fontSize: 18 }}>🔑</span>
              <span style={{ color: theme.text, fontSize: 14, fontWeight: 600 }}>Change password</span>
            </div>
            <span style={{ color: theme.textDim, fontSize: 18, transform: section === "password" ? "rotate(90deg)" : "none", transition: "transform 0.2s" }}>›</span>
          </button>
          {section === "password" && (
            <div style={{ padding: "0 16px 16px", borderTop: `1px solid ${theme.border}` }}>
              {passStep === "form" && (
                <div style={{ marginTop: 14 }}>
                  <Input label="Current password" type="password" placeholder="••••••••" value={oldPass} onChange={setOldPass} />
                  <Input label="New password" type="password" placeholder="Min. 8 characters" value={newPass} onChange={setNewPass} />
                  <p style={{ color: theme.textDim, fontSize: 12, lineHeight: 1.5, marginBottom: 12 }}>
                    We'll send a verification email to <strong style={{ color: theme.textMuted }}>{email}</strong> to confirm this change.
                  </p>
                  <Btn onClick={requestPasswordChange} style={{ padding: "12px", opacity: oldPass && newPass.length >= 8 ? 1 : 0.4 }}>
                    Send verification email
                  </Btn>
                </div>
              )}
              {passStep === "sent" && (
                <div style={{ marginTop: 14 }}>
                  <div style={{ textAlign: "center", marginBottom: 16 }}>
                    <div style={{ fontSize: 34, marginBottom: 8 }}>📬</div>
                    <p style={{ color: theme.text, fontWeight: 600, fontSize: 14, marginBottom: 4 }}>Check your inbox</p>
                    <p style={{ color: theme.textMuted, fontSize: 12, lineHeight: 1.5 }}>
                      We sent a 6-digit code to <strong>{email}</strong>. Enter it below to confirm the change.
                    </p>
                  </div>
                  <Input label="Verification code" placeholder="e.g. 483 291" value={verifyCode} onChange={setVerifyCode} />
                  <Btn onClick={confirmPasswordChange} style={{ padding: "12px", opacity: verifyCode.length >= 4 ? 1 : 0.4 }}>
                    Confirm new password
                  </Btn>
                  <button onClick={() => setPassStep("form")} style={{ background: "none", border: "none", color: theme.textMuted, fontSize: 12, cursor: "pointer", fontFamily: "inherit", width: "100%", padding: "10px 0 0", textAlign: "center" }}>
                    ← Go back
                  </button>
                </div>
              )}
              {passStep === "done" && (
                <div style={{ marginTop: 14, padding: "14px 12px", background: "#4ade8018", border: "1px solid #4ade8040", borderRadius: 10, textAlign: "center" }}>
                  <div style={{ color: theme.green, fontSize: 22, marginBottom: 4 }}>✓</div>
                  <p style={{ color: theme.green, fontSize: 13, fontWeight: 600 }}>Password updated successfully</p>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Servers shortcut */}
        <label style={{ color: theme.textMuted, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", display: "block", marginBottom: 10 }}>
          Self-hosting
        </label>
        <button
          onClick={onServers}
          style={{
            width: "100%", background: theme.surface, border: `1px solid ${theme.border}`,
            borderRadius: 14, padding: "16px", display: "flex", justifyContent: "space-between",
            alignItems: "center", cursor: "pointer", marginBottom: 20,
          }}>
          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            <span style={{ fontSize: 18 }}>🖥</span>
            <div style={{ textAlign: "left" }}>
              <div style={{ color: theme.text, fontSize: 14, fontWeight: 600 }}>Self-hosted servers</div>
              <div style={{ color: theme.textMuted, fontSize: 12 }}>2 servers connected</div>
            </div>
          </div>
          <span style={{ color: theme.textDim, fontSize: 18 }}>›</span>
        </button>

        {/* Danger zone */}
        <label style={{ color: theme.textMuted, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", display: "block", marginBottom: 10 }}>
          Danger zone
        </label>
        <div style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 14, overflow: "hidden", marginBottom: 8 }}>
          <button
            onClick={() => setSection(section === "danger" ? null : "danger")}
            style={{ width: "100%", padding: "16px", background: "none", border: "none", display: "flex", justifyContent: "space-between", alignItems: "center", cursor: "pointer" }}>
            <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
              <span style={{ fontSize: 18 }}>🗑</span>
              <span style={{ color: "#ff6666", fontSize: 14, fontWeight: 600 }}>Delete account</span>
            </div>
            <span style={{ color: theme.textDim, fontSize: 18, transform: section === "danger" ? "rotate(90deg)" : "none", transition: "transform 0.2s" }}>›</span>
          </button>
          {section === "danger" && (
            <div style={{ padding: "0 16px 16px", borderTop: `1px solid ${theme.border}` }}>
              <p style={{ color: theme.textMuted, fontSize: 13, lineHeight: 1.6, marginTop: 14, marginBottom: 14 }}>
                This permanently deletes your account and all synced data. This cannot be undone.
              </p>
              <button style={{
                width: "100%", padding: "12px", borderRadius: 10,
                background: "#ff444418", border: "1px solid #ff444440",
                color: "#ff8888", fontWeight: 700, fontSize: 14, cursor: "pointer", fontFamily: "inherit",
              }}>Delete my account</button>
            </div>
          )}
        </div>

        <button style={{ background: "none", border: "none", color: theme.textMuted, fontSize: 14, cursor: "pointer", fontFamily: "inherit", marginTop: 8, display: "block", width: "100%", textAlign: "center", padding: "12px" }}>
          Sign out
        </button>
      </div>
    </div>
  );
}

// ── Screen: Self-Hosted Servers ───────────────────────────────────────────────

const DEFAULT_SERVERS = [
  { id: "s1", name: "Home server",    url: "https://sync.alexhome.net",    token: true,  status: "connected", vaults: ["Personal Notes"] },
  { id: "s2", name: "Work instance",  url: "https://fsync.mycompany.com",  token: true,  status: "connected", vaults: ["Work Docs", "Team Wiki"] },
];

function ServersScreen({ onBack }) {
  const [servers, setServers] = useState(DEFAULT_SERVERS);
  const [adding, setAdding]   = useState(false);
  const [newName, setNewName] = useState("");
  const [newUrl, setNewUrl]   = useState("");
  const [newToken, setNewToken] = useState("");
  const [testing, setTesting] = useState(null);
  const [testResult, setTestResult] = useState(null);
  const [expanded, setExpanded] = useState(null);
  const [removeTarget, setRemoveTarget] = useState(null);

  function testConnection(id, url) {
    setTesting(id);
    setTestResult(null);
    setTimeout(() => {
      setTesting(null);
      setTestResult({ id, ok: url.startsWith("https") });
      setTimeout(() => setTestResult(null), 3000);
    }, 1400);
  }

  function addServer() {
    if (!newName || !newUrl.startsWith("http")) return;
    setServers(prev => [...prev, {
      id: `s${Date.now()}`,
      name: newName,
      url: newUrl,
      token: !!newToken,
      status: "connected",
      vaults: [],
    }]);
    setNewName(""); setNewUrl(""); setNewToken("");
    setAdding(false);
  }

  function removeServer(id) {
    setServers(prev => prev.filter(s => s.id !== id));
    setRemoveTarget(null);
    setExpanded(null);
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", background: theme.bg }}>
      <div style={{ padding: "52px 24px 18px", borderBottom: `1px solid ${theme.border}` }}>
        <BackBtn onClick={onBack} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
          <div>
            <h2 style={{ color: theme.text, fontSize: 22, fontWeight: 700, fontFamily: "Georgia, serif", marginBottom: 3 }}>Servers</h2>
            <p style={{ color: theme.textMuted, fontSize: 13 }}>Self-hosted FreeSync instances.</p>
          </div>
          <button onClick={() => { setAdding(!adding); setNewName(""); setNewUrl(""); setNewToken(""); }} style={{
            background: adding ? theme.surfaceHigh : "linear-gradient(135deg,#7c5cfc,#a78bfa)",
            border: "none", borderRadius: 10, padding: "8px 14px",
            color: "#fff", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit",
          }}>
            {adding ? "Cancel" : "+ Add"}
          </button>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "20px 24px 40px" }}>

        {/* Add server form */}
        {adding && (
          <div style={{
            background: "#7c5cfc0e", border: `1.5px solid ${theme.accent}`,
            borderRadius: 14, padding: "16px", marginBottom: 20,
          }}>
            <label style={{ color: theme.accent, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", display: "block", marginBottom: 12 }}>
              New server
            </label>
            <Input label="Nickname" placeholder="e.g. Home server" value={newName} onChange={setNewName} />
            <div style={{ marginBottom: 12 }}>
              <label style={{ color: theme.textMuted, fontSize: 11, fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase", display: "block", marginBottom: 6 }}>Server URL</label>
              <input
                type="url" placeholder="https://sync.yourdomain.com"
                value={newUrl} onChange={e => setNewUrl(e.target.value)}
                style={{
                  width: "100%", padding: "11px 13px", borderRadius: 10,
                  background: theme.surfaceHigh, border: `1.5px solid ${theme.border}`,
                  color: theme.text, fontSize: 13, outline: "none",
                  fontFamily: "'Courier New', monospace", boxSizing: "border-box",
                }}
              />
            </div>
            <div style={{ marginBottom: 16 }}>
              <AuthTokenLabel />
              <input
                type="password" placeholder="Server auth token"
                value={newToken} onChange={e => setNewToken(e.target.value)}
                style={{
                  width: "100%", padding: "11px 13px", borderRadius: 10,
                  background: theme.surfaceHigh, border: `1.5px solid ${theme.border}`,
                  color: theme.text, fontSize: 13, outline: "none",
                  fontFamily: "'Courier New', monospace", boxSizing: "border-box",
                }}
              />
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <button
                onClick={() => testConnection("new", newUrl)}
                disabled={!newUrl.startsWith("http")}
                style={{
                  flex: 1, padding: "11px", borderRadius: 10,
                  background: theme.surfaceHigh, border: `1px solid ${theme.border}`,
                  color: theme.textMuted, fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: "inherit",
                  opacity: newUrl.startsWith("http") ? 1 : 0.4,
                }}>
                {testing === "new" ? "Testing…" : testResult?.id === "new" ? (testResult.ok ? "✓ Reachable" : "✗ Unreachable") : "Test connection"}
              </button>
              <Btn onClick={addServer} style={{ flex: 1, padding: "11px", opacity: newName && newUrl.startsWith("http") ? 1 : 0.4 }}>
                Add server
              </Btn>
            </div>
          </div>
        )}

        {/* Server list */}
        {servers.length === 0 && (
          <div style={{ textAlign: "center", padding: "40px 0", color: theme.textDim, fontSize: 14 }}>
            <div style={{ fontSize: 36, marginBottom: 10 }}>🖥</div>
            No servers added yet.<br />Add one above to get started.
          </div>
        )}

        {servers.map(server => (
          <div key={server.id} style={{ marginBottom: 10 }}>
            {removeTarget === server.id ? (
              <div style={{ background: "#ff444412", border: "1px solid #ff444330", borderRadius: 14, padding: "14px 16px" }}>
                <p style={{ color: theme.text, fontSize: 14, marginBottom: 4 }}>Remove <strong style={{ color: theme.accent }}>{server.name}</strong>?</p>
                <p style={{ color: theme.textMuted, fontSize: 12, marginBottom: 14 }}>Vaults assigned to this server won't sync until reassigned.</p>
                <div style={{ display: "flex", gap: 8 }}>
                  <button onClick={() => removeServer(server.id)} style={{ flex: 1, padding: "10px", borderRadius: 10, border: "1px solid #ff444440", background: "#ff444422", color: "#ff8888", fontWeight: 700, cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Remove</button>
                  <button onClick={() => setRemoveTarget(null)} style={{ flex: 1, padding: "10px", borderRadius: 10, border: `1px solid ${theme.border}`, background: theme.surface, color: theme.textMuted, cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Cancel</button>
                </div>
              </div>
            ) : (
              <div style={{ background: theme.surface, border: `1px solid ${expanded === server.id ? theme.accent : theme.border}`, borderRadius: 14, overflow: "hidden", transition: "border-color 0.2s" }}>
                {/* Server row */}
                <button
                  onClick={() => setExpanded(expanded === server.id ? null : server.id)}
                  style={{ width: "100%", padding: "14px 16px", background: "none", border: "none", display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }}>
                  <div style={{
                    width: 36, height: 36, borderRadius: 10, flexShrink: 0,
                    background: server.status === "connected" ? "#4ade8018" : "#ff444418",
                    border: `1px solid ${server.status === "connected" ? "#4ade8030" : "#ff444430"}`,
                    display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18,
                  }}>🖥</div>
                  <div style={{ flex: 1, textAlign: "left", minWidth: 0 }}>
                    <div style={{ color: theme.text, fontSize: 14, fontWeight: 600 }}>{server.name}</div>
                    <div style={{ color: theme.textDim, fontSize: 11, fontFamily: "'Courier New', monospace", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {server.url}
                    </div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }}>
                    <div style={{ width: 7, height: 7, borderRadius: "50%", background: server.status === "connected" ? theme.green : "#ff6666" }} />
                    <span style={{ color: server.status === "connected" ? theme.green : "#ff6666", fontSize: 11, fontWeight: 600 }}>
                      {server.status === "connected" ? "Online" : "Offline"}
                    </span>
                    <span style={{ color: theme.textDim, fontSize: 16, marginLeft: 4, transform: expanded === server.id ? "rotate(90deg)" : "none", transition: "transform 0.2s", display: "block" }}>›</span>
                  </div>
                </button>

                {/* Expanded details */}
                {expanded === server.id && (
                  <div style={{ borderTop: `1px solid ${theme.border}`, padding: "14px 16px" }}>
                    {/* Vault assignments */}
                    {server.vaults.length > 0 && (
                      <div style={{ marginBottom: 14 }}>
                        <label style={{ color: theme.textMuted, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", display: "block", marginBottom: 8 }}>
                          Assigned vaults
                        </label>
                        {server.vaults.map(v => (
                          <div key={v} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                            <span style={{ fontSize: 14 }}>⟁</span>
                            <span style={{ color: theme.textMuted, fontSize: 13 }}>{v}</span>
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Token indicator */}
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
                      <span style={{ color: theme.textDim, fontSize: 12 }}>Auth token:</span>
                      <span style={{ color: server.token ? theme.green : theme.textDim, fontSize: 12, fontWeight: 600 }}>
                        {server.token ? "✓ Configured" : "None"}
                      </span>
                    </div>

                    {/* Test result */}
                    {testResult?.id === server.id && (
                      <div style={{
                        padding: "9px 12px", borderRadius: 8, marginBottom: 12, fontSize: 13, fontWeight: 600,
                        background: testResult.ok ? "#4ade8018" : "#ff444418",
                        border: `1px solid ${testResult.ok ? "#4ade8040" : "#ff444440"}`,
                        color: testResult.ok ? theme.green : "#ff8888",
                      }}>
                        {testResult.ok ? "✓ Server is reachable" : "✗ Could not reach server"}
                      </div>
                    )}

                    <div style={{ display: "flex", gap: 8 }}>
                      <button
                        onClick={() => testConnection(server.id, server.url)}
                        style={{
                          flex: 1, padding: "10px", borderRadius: 10,
                          background: theme.surfaceHigh, border: `1px solid ${theme.border}`,
                          color: theme.textMuted, fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: "inherit",
                        }}>
                        {testing === server.id ? "Testing…" : "Test"}
                      </button>
                      <button
                        style={{ flex: 1, padding: "10px", borderRadius: 10, background: theme.surfaceHigh, border: `1px solid ${theme.border}`, color: theme.textMuted, fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>
                        Edit
                      </button>
                      <button
                        onClick={() => setRemoveTarget(server.id)}
                        style={{ padding: "10px 14px", borderRadius: 10, background: "#ff444412", border: "1px solid #ff444430", color: "#ff8888", fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>
                        ✕
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}

        {servers.length > 0 && (
          <p style={{ color: theme.textDim, fontSize: 12, textAlign: "center", marginTop: 16, lineHeight: 1.6 }}>
            Each vault can be assigned to a different server.{"\n"}Manage vault–server assignments from the vault settings.
          </p>
        )}
      </div>
    </div>
  );
}

// ── App Shell ─────────────────────────────────────────────────────────────────

const SCREENS = ["onboarding","signup","signin","vaults","share","plugin","upgrade","account","servers"];
const LABELS  = {
  onboarding: "01 — onboarding",
  signup:     "02 — sign up",
  signin:     "03 — sign in",
  vaults:     "04 — vault list",
  share:      "05 — share vault",
  plugin:     "06 — obsidian plugin",
  upgrade:    "07 — upgrade",
  account:    "08 — account settings",
  servers:    "09 — self-hosted servers",
};

export default function App() {
  const [screen, setScreen] = useState("onboarding");
  const go = s => () => setScreen(s);

  const screens = {
    onboarding: <OnboardingScreen    onSignUp={go("signup")}  onSignIn={go("signin")} />,
    signup:     <SignUpScreen        onBack={go("onboarding")} onDone={go("vaults")} />,
    signin:     <SignInScreen        onBack={go("onboarding")} onDone={go("vaults")} />,
    vaults:     <VaultListScreen     onVaultTap={go("plugin")} onShare={go("share")} onUpgrade={go("upgrade")} onAccount={go("account")} onServers={go("servers")} />,
    share:      <VaultShareScreen    onBack={go("vaults")} />,
    plugin:     <PluginPreviewScreen onBack={go("vaults")} />,
    upgrade:    <UpgradeScreen       onBack={go("vaults")} />,
    account:    <AccountSettingsScreen onBack={go("vaults")} onServers={go("servers")} onUpgrade={go("upgrade")} />,
    servers:    <ServersScreen       onBack={go("account")} />,
  };

  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100vh", background: "#080808", fontFamily: "-apple-system, 'SF Pro Display', sans-serif" }}>
      {/* Nav dots */}
      <div style={{ position: "fixed", top: 24, left: "50%", transform: "translateX(-50%)", display: "flex", gap: 7, zIndex: 100 }}>
        {SCREENS.map(s => (
          <button key={s} onClick={() => setScreen(s)} style={{
            width: screen === s ? 22 : 8, height: 8, borderRadius: 4, border: "none",
            cursor: "pointer", background: screen === s ? theme.accent : theme.border,
            transition: "all 0.25s", padding: 0,
          }} />
        ))}
      </div>

      {/* Phone frame */}
      <div style={{ width: 390, height: 844, borderRadius: 48, background: theme.bg, overflow: "hidden", position: "relative", border: "1px solid #333", boxShadow: "0 40px 120px #00000088, 0 0 0 1px #222 inset" }}>
        <div style={{ position: "absolute", top: 12, left: "50%", transform: "translateX(-50%)", width: 120, height: 34, background: "#000", borderRadius: 20, zIndex: 200 }} />
        {screens[screen]}
      </div>

      {/* Screen label */}
      <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", color: "#333", fontSize: 11, fontFamily: "'Courier New', monospace", letterSpacing: 2, textTransform: "uppercase" }}>
        {LABELS[screen]}
      </div>
    </div>
  );
}
